using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class BillGates
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "If something is expensive to develop, and somebody's not going to get paid, it won't get developed. So you decide: Do you want software to be written, or not?", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Instead of buying airplanes and playing around like some of our competitors, we've rolled almost everything back into the company.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "To create a new standard, it takes something that's not just a little bit different; it takes something that's really new and really captures people's imagination — and the Macintosh, of all the machines I've ever seen, is the only one that meets that standard.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The next generation of interesting software will be done on the Macintosh, not the IBM PC.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "There's only one trick in software, and that's using a piece of software that's already been written.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "If people had understood how patents would be granted when most of today's ideas were invented, and had taken out patents, the industry would be at a complete standstill today.... The solution to this is patent exchanges with large companies and patenting as much as we can.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Gary Kildall was one of the original pioneers of the PC revolution. He was a very creative computer scientist who did excellent work. Although we were competitors, I always had tremendous respect for his contributions to the PC industry. His untimely death was very unfortunate and he and his work will be missed.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "There are no significant bugs in our released software that any significant number of users want fixed. ... I'm saying we don't do a new version to fix bugs. We don't. Not enough people would buy it. You can take a hundred people using Microsoft Word. Call them up and say \"Would you buy a new version because of bugs?\" You won't get a single person to say they'd buy a new version because of bugs. We'd never be able to sell a release on that basis.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "In terms of doing things I take a fairly scientific approach to why things happen and how they happen. I don't know if there's a god or not, but I think religious principles are quite valid.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "What we're saying to people is that every idea about ease-of-use, we can develop in software, for the PC, without asking them to buy new hardware, without asking them to throw away their old applications.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Just in terms of allocation of time resources, religion is not very efficient. There's a lot more I could be doing on a Sunday morning.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Any operating system without a browser is going to be fucking out of business. Should we improve our product, or go out of business?", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "It's possible, you can never know, that the universe exists only for me. If so, it's sure going well for me, I must admit.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We've done some good work, but all of these products become obsolete so fast... It will be some finite number of years, and I don't know the number — before our doom comes.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "One thing we have got to change in our strategy - allowing Office documents to be rendered very well by other peoples browsers is one of the most destructive things we could do to the company. We have to stop putting any effort into this and make sure that Office documents very well depends on PROPRIETARY IE capabilities.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Although about 3 million computers get sold every year in China, but people don't pay for the software. Someday they will, though. As long as they are going to steal it, we want them to steal ours. They'll get sort of addicted, and then we'll somehow figure out how to collect sometime in the next decade.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Sometimes we do get taken by surprise. For example, when the Internet came along, we had it as a fifth or sixth priority. It wasn't like somebody told me about it and I said, \"I don't know how to spell that.\" I said, \"Yeah, I've got that on my list, so I'm okay.\" But there came a point when we realized it was happening faster and was a much deeper phenomenon than had been recognized in our strategy.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Your most unhappy customers are your greatest source of learning.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Microsoft has had clear competitors in the past. It's a good thing we have museums to document that.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We don't have the user centricity. Until we understand context, which is way beyond presence — presence is the most trivial notion, just am I on this device or not; it doesn't say am I meeting with something, am I focused on writing something.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Like almost everyone who uses e-mail, I receive a ton of spam every day. Much of it offers to help me get out of debt or get rich quick. It would be funny if it weren't so irritating.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Spam will be a thing of the past in two years' time.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Does the e-mail say it's about 'enlargement' — that might be spam.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Personal computing today is a rich ecosystem encompassing massive PC-based data centers, notebook and Tablet PCs, handheld devices, and smart cell phones. It has expanded from the desktop and the data center to wherever people need it — at their desks, in a meeting, on the road or even in the air.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "If you show people the problems and you show people the solutions they will be moved to act.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Understand that this is the last physical format there will ever be.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I wish I wasn't ... There's nothing good that comes out of that. You get more visibility as a result of it.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Stolen's a strong word. It's copyrighted content that the owner wasn't paid for. So yes.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I'm a big believer that as much as possible, and there's obviously political limitations, freedom of migration is a good thing.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "If you just want to say, \"Steve Jobs invented the world, and then the rest of us came along,\" that's fine. If you're interested, Jim Allchin will be glad to educate you feature by feature what the truth is. ... Let's be realistic, who came up with \"File/Edit/View/Help\"? Do you want to go back to the original Mac and think about where those interface concepts came from?", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "It's easier for our software to compete with Linux when there's piracy than when there's not.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "[I]t's not like I sit there and feel the same way I did with iPhone where I say, \"Oh my God, Microsoft didn't aim high enough.\" It's a nice reader, but there's nothing on the iPad I look at and say, \"Oh, I wish Microsoft had done it.\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Just giving people devices has a really horrible track record. You really have to change the curriculum and the teacher. And it's never going to work on a device where you don't have a keyboard-type input. Students aren't there just to read things. They're actually supposed to be able to write and communicate. And so it's going to be more in the PC realm—it's going to be a low-cost PC that lets them be highly interactive.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The only way you can get to the very positive scenario [in the fight against climate change] is by great innovation. Innovation really does bend the curve.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Most governments take advantage of their scientists and listen to them. They don't undermine them and attack them.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Usually, you'd expect the worst to be the \"ground zero\" country — in this case, China, then the next wave, which was all in Asia, and then in Europe, and then finally, the U.S. We had all this community spread. With a travel ban, where you actually force people to come back from China, you have to have a way to be able to either just assume they're infected and quarantine them, or test them. And then if they test positive, to have that enforced quarantine. We actually seeded a lot of infection by saying, 'Okay, everybody, residents and citizens come back (and not testing or quarantining).'", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We always have to be serious about public health in a global sense and surveillance for \"the next one\", because we don't know where it will emerge.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Well, one thing that everybody may not be aware of is how fantastic the CDC has been historically. They're the best in the world. They train themselves in terms of how to communicate, including getting bad news out and getting people to take measures that protect themselves. And they've been muzzled.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "You can make sure wind turbines can deal with the cold", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The climate is not the end of the planet. So the planet is going to be fine", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "\"The big concern is about the generations yet to come when [AI] gets way smarter than it is right now. And if a person with Mal intent was using that, say, for a cyberattack, or to make a deep fake that makes a politician look like they're doing something awful, or even one of your relatives saying, okay, I've been kidnapped.\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "If you eventually get a society where you only have to work three days a week, that’s probably OK. If you free up human labor, you can help elder people better, have smaller class sizes – you know, the demand for labor to do good things is still there. And then if you ever get beyond that, you have a lot of leisure time and you’ll have to figure out what to do with it.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "\"So the idea of being able to explain something in a succinct form is such a cool thing, and it requires you to know a field so well.\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "India is an example of a country where there's plenty of things that are difficult there -- the health, education, nutrition is improving and they are stable enough and generating their own government revenue enough that it's very likely that 20 years from now people will be dramatically better off and it's kind of a laboratory to try things that then when you prove them out in India, you can take to other places. And so our biggest non-US office for the Foundation is in India and the most number of pilot roll out things we're doing anywhere in the world are with partners in India. If you go there and you've never been you might think whoa this is a chaotic place and you know you're not used to so many levels of income all being on the street at the same time but you will get a sense of vibrancy.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Within 10 years, AI will replace many doctors and teachers—humans won’t be needed ‘for most things’. It’s very profound and even a little bit scary — because it’s happening very quickly, and there is no upper bound,.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "\"The picture of the world's richest man killing the world's poorest children is not a pretty one.\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "\"People will say a lot of things about me when I die, but I am determined that 'he died rich' will not be one of them.\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "One of the best things I read was an 1889 essay by Andrew Carnegie called The Gospel of Wealth. It makes the case that the wealthy have a responsibility to return their resources to society, a radical idea at the time that laid the groundwork for philanthropy as we know it today. In the essay’s most famous line, Carnegie argues that “the man who dies thus rich dies disgraced.” I have spent a lot of time thinking about that quote lately. People will say a lot of things about me when I die, but I am determined that \"he died rich\" will not be one of them. There are too many urgent problems to solve for me to hold onto resources that could be used to help people. That is why I have decided to give my money back to society much faster than I had originally planned. I will give away virtually all my wealth through the Gates Foundation over the next 20 years to the cause of saving and improving lives around the world.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The best way to prepare [to be a programmer] is to write programs, and to study great programs that other people have written. In my case, I went to the garbage cans at the Computer Science Center and fished out listings of their operating system.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "You've got to be willing to read other people's code, and then write your own, then have other people review your code. You've got to want to be in this incredible feedback loop where you get the world-class people to tell you what you're doing wrong...", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The finest pieces of software are those where one individual has a complete sense of exactly how the program works. To have that, you have to really love the program and concentrate on keeping it simple, to an incredible degree.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We're no longer in the days where everything is super well crafted. But at the heart of the programs that make it to the top, you'll find that the key internal code was done by a few people who really know what they were doing.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Unfortunately, many programs are so big that there is no one individual who really knows all the pieces, and so the amount of code sharing you get isn't as great. Also, the opportunity to go back and really rewrite something isn't quite as great, because there's always a new set of features that you're adding on to the same program.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The worst programs are the ones where the programmers doing the original work don't lay a solid foundation, and then they're not involved in the program in the future.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Programs today get very fat; the enhancements tend to slow the programs down because people put in special checks. When they want to add some feature, they'll just stick in these checks without thinking how they might slow the thing down.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Before Paul and I started the company, we had been involved in some large-scale software projects that were real disasters. They just kept pouring people in, and nobody knew how they were going to stabilize the project. We swore to ourselves that we would do better.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Success is a lousy teacher. It seduces smart people into thinking they can't lose.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "One of the wonderful things about the information highway is that virtual equity is far easier to achieve than real-world equity...We are all created equal in the virtual world and we can use this equality to help address some of the sociological problems that society has yet to solve in the physical world,\"", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "This leads to the paradox, that because the disease is only in the poor countries, there is not much investment. For example, there is more money put into baldness drugs, than are put into malaria. Now, baldness, it is a terrible thing [audience laughter] and rich men are afflicted, so that is why that priority is set.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The harsh mathematics of polio makes it clear: We cannot maintain a level of one thousand or two thousand cases a year. Either we eradicate polio, or we return to the days of tens of thousands of cases per year. That is no alternative at all. We don't let children die because it is fatiguing to save them. Our commitment as a foundation is to work with partners until no children die from polio.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The success of the Nigeria programme hinges on the active participation of everyone to make sure that all children are reached by National Immunization Days (NIDs), Immunization Plus Days (IPDs) and the routine immunization programme, if the country capitalizes on the commitments I've heard in the past two days, Nigeria can lead the way to a polio-free Africa.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We are in the end game, I'm optimistic that we will be successful. I'm personally very committed.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I'd like to start by telling you about my wife Melinda's Aunt Myra. We see her a few times a year. Aunt Myra worked for many years taking reservations for Delta Airlines. She lived in New Orleans until Hurricane Katrina, and then she moved to Dallas, Melinda's hometown. She loves to see our kids. When we all get together, she'll sit down on the floor and play games with them. Aunt Myra also has polio. She's in braces, and she has been ever since she was a little girl. Our children only know what polio is because of their aunt. Otherwise, the disease would just be another historical fact they learn about in school. In fact, even though I was born just three years after one of the worst polio epidemics in American history, I didn't know anyone with polio when I was growing up. That's how far we've come.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "In the last 20 years, thanks to your hard work, polio has declined by 99 percent. In 1988, 350,000 people got polio. By 2008, the number was down to just a couple of thousand.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "First we've got population. Now, the world today has 6.8 billion people. That's headed up to about nine billion. Now, if we do a really great job on new vaccines, health care, reproductive health services, we could lower that (forecast) by, perhaps, 10 or 15 percent, but there we see an increase of about 1.3 (per year).", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Let's burn the 99%.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "He [Steve Jobs] showed me the boat he was working on ... and talked about how he's looking forward to being on it, even though we both knew there was a good chance that wouldn't happen.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "The moral systems of religion, I think, are superimportant. We've raised our kids in a religious way; they've gone to the Catholic church that Melinda goes to and I participate in. I've been very lucky, and therefore I owe it to try and reduce the inequity in the world. And that's kind of a religious belief. I mean, it's at least a moral belief.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I agree with people like Richard Dawkins that mankind felt the need for creation myths. Before we really began to understand disease and the weather and things like that, we sought false explanations for them. Now science has filled in some of the realm – not all – that religion used to fill. But the mystery and the beauty of the world is overwhelmingly amazing, and there's no scientific explanation of how it came about. To say that it was generated by random numbers, that does seem, you know, sort of an uncharitable view. I think it makes sense to believe in God, but exactly what decision in your life you make differently because of it, I don't know.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We would like every country to be self-sufficient so that both in terms of running a good primary health care system and funding a good primary health care system, it's all OK, and they just participate in regional bodies that have standby capacity to deal with these things. Africa, of all the places in the world, is the furthest behind on being able to do that. And through aid, health and health systems in Africa have improved very, very dramatically.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "...this has been a mismanaged situation every step of the way. It's shocking. It's unbelievable — the fact that we would be among the worst in the world.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "40,000 people came out of China, 'cause we didn't ban the rest of them citizens from coming back, so we created this rush and we didn't have the ability to quarantine those people, and that seeded the disease here", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We are running the worst testing system, in terms of who gets access to it, of any country", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Halting funding for the World Health Organization during a world health crisis is as dangerous as it sounds.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "There are two numbers you need to know about climate change. The first is 51 billion. The other is zero. Fifty-one billion is how many tons of greenhouse gases the world typically adds to the atmosphere every year. . . . Zero is what we need to aim for [by the year 2050 to] stop the warming and avoid the worst effects of climate change . . . .", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I [have become] convinced of three things: 1. To avoid a climate disaster, we have to get to get to zero {net emissions} by the year 2050}. 2. We need to deploy the tools we already have, like solar and wind, faster and smarter. 3. And we need to create and roll out breakthrough technologies that can take us the rest of the way.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "When it comes to climate change, I know innovation isn’t the only thing we need. But we cannot keep the earth livable without it. Techno-fixes are not sufficient, but they are necessary.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Deploying today’s renewables and improving transmission couldn’t be more important. . . . Unless we use large amounts of nuclear energy . . . every path to zero in the United States will require us to install as much wind and solar power as we can build and find room for. . . . [M]ost countries aren’t as lucky as the United States when it comes to solar and wind resources. . . . That’s why, even as we deploy, deploy, deploy solar and wind, the world is going to need some new clean electricity inventions too.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "[W]ith transportation, the zero-carbon future is basically this: Use electricity to run all the vehicles we can, and get cheap alternative fuels for the rest. In the first group are passenger cars and trucks, light and medium trucks, and buses. In the second group are long-distance trucks, trains, airplanes, and container ships.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "To get [the breakthroughs on the \"Technologies needed\" list] ready soon enough to make a difference, governments need to . . . [q]uintuple clean energy and climate-related R&D over the next decade. . . .", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "It helps to set ambitious goals and commit to meeting them, the way countries around the world did with the 2015 Paris Agreement. It’s easy to mock international agreements, but they’re part of how progress happens: If you like having an ozone layer, you can thank an international agreement called the Montreal Protocol.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "As a Citizen . . . Make calls, write letters, attend town halls. . . . [M]ake clear that this is an issue that will help determine how you vote. . . . Look locally as well as nationally. . . . Run for office.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "As a Consumer . . . Sign up for a green pricing program with your electric utility. . . . Reduce your home's emissions. . . . Buy an electric vehicle. . . . Try a plant-based burger.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "We should spend the next decade focusing on the technologies, [governmental] policies and market structures that will put us on the path to eliminating greenhouse gases by 2050. It's hard to think of a better response to a miserable [year of COVID-19 disruptions during] 2020 than spending the next ten years dedicating ourselves to this ambitious goal.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "I see little commercial potential for the internet for the next 10 years.", Author = "Bill Gates" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Bill_Gates", Text = "Intellectual property has the shelf life of a banana.", Author = "Bill Gates" },
        };
    }
}